package gala_tui

import (
	"encoding/base64"
	"encoding/binary"
	"sync"
)

// The world's coastlines for ShapeWorldMap, from Natural Earth
// (naturalearthdata.com), which is in the public domain: the 1:110m set for
// MapLow, and the 1:50m set simplified to 0.05° (Douglas–Peucker) for
// MapHigh — about 5,000 and 22,000 points.
//
// Kept in Go rather than GALA because they are data, not code: a GALA array
// literal of 27,000 coordinates is a long transpile for nothing. Each point
// is (longitude×100, latitude×100) as two little-endian int16s, and the pair
// (0x7FFF, 0x7FFF) ends a coastline. Regenerate with
// tools/worldmap/pack.py.

// worldMapSegments is the coastlines as line segments, flattened —
// x1, y1, x2, y2, x1, y1, … in degrees of longitude and latitude — decoded
// once, the first time a map is drawn.
func worldMapSegments(high bool) []float64 {
	if high {
		return worldMapHigh()
	}
	return worldMapLow()
}

// worldMapEach calls f with each coastline segment, in degrees. The loop is
// here rather than in GALA, which cannot see a Go slice's type to index it.
// It runs per frame over up to 22,000 segments and allocates nothing.
func worldMapEach(high bool, f func(x1, y1, x2, y2 float64)) {
	segs := worldMapSegments(high)
	for i := 0; i+3 < len(segs); i += 4 {
		f(segs[i], segs[i+1], segs[i+2], segs[i+3])
	}
}

var (
	worldMapLow  = sync.OnceValue(func() []float64 { return decodeWorldMap(worldMapLowData) })
	worldMapHigh = sync.OnceValue(func() []float64 { return decodeWorldMap(worldMapHighData) })
)

func decodeWorldMap(data string) []float64 {
	raw, err := base64.StdEncoding.DecodeString(data)
	if err != nil {
		// The data is a constant: a decode failure is a bad regeneration,
		// and an empty map with no error would hide it.
		panic("gala_tui: corrupt world map data: " + err.Error())
	}
	var segs []float64
	var px, py float64
	started := false
	for i := 0; i+4 <= len(raw); i += 4 {
		x := int16(binary.LittleEndian.Uint16(raw[i:]))
		y := int16(binary.LittleEndian.Uint16(raw[i+2:]))
		if x == 0x7FFF && y == 0x7FFF {
			started = false
			continue
		}
		fx, fy := float64(x)/100, float64(y)/100
		if started {
			segs = append(segs, px, py, fx, fy)
		}
		px, py, started = fx, fy, true
	}
	return segs
}

